import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BNuav-ne.js";const c=JSON.parse('{"title":"关于项目","description":"","frontmatter":{},"headers":[],"relativePath":"guide/my.md","filePath":"guide/my.md","lastUpdated":1792557099000}'),o={name:"guide/my.md"};function p(n,e,i,l,_,m){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="关于项目" tabindex="-1">关于项目 <a class="header-anchor" href="#关于项目" aria-label="Permalink to &quot;关于项目&quot;">​</a></h1><p>本文是作者早期的项目随笔，保留原文。文中年限和维护计划是写作时的情况；版本变化请看<a href="/Cnblogs-Theme-SimpleMemory/v2.1/dist/changelog/">更新历史</a>，问题反馈请使用 <a href="https://github.com/BNDong/Cnblogs-Theme-SimpleMemory/issues" target="_blank" rel="noreferrer">Issues</a>。</p><p>不知不觉项目坚挺了 5 年了，已经记不清当初为什么要搞这个项目了，只记得开始搞这个时候还是个小白，那是真的菜的一逼，哈哈，那时候还对技术充满了热情，虽然菜但是爱。 说实话，我也不知道为啥这么多人用，每天看着 star 数量一脸懵逼！！！</p><p>关于项目代码：我入互联网到现在一直走的是后端的岗位，现在依然。所以项目的源码，可能在规划和语法上有很大的不足，请大家见谅！</p><p>关于群的问题：超多人问我有没有关于这个项目的群。这个项目不会拉群的，我一直感觉如果拉群，可能性质就变了，而且项目的技术也没有值得吹捧的，只是个博客园辅助的东西，我本身也是不爱天天群里划水的人，有问题 Issues 是最好的处理方式。主要也是怕，众口难调，还依稀记得有人因为项目问题，说我不负责，没开源精神，吧啦吧啦～</p><p>5 年了，我已经从当初的小白，成长到了今天大白，年龄也成功跨越到了中年。年龄越大责任越大这话真不是盖的，现在每天要忙于工作，照顾家庭，精力已经所剩不多了，所以项目往后更多的是倾向维护，不会进行大的改动了，欢迎有大佬可以继续推进项目。</p><p>感谢使用项目的人。同时感谢你，在我无聊的时候，听我说废话，哈哈。就这样，祝：平安喜乐、万事胜意！</p><hr><p style="text-align:right;color:#aaa;font-style:italic;font-size:14px;">2020.08.23 BNDong</p>',9)])])}const h=t(o,[["render",p]]);export{c as __pageData,h as default};
